<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['pharmacist','manager','admin']); $db=db(); $days=30; $expired=$db->query("SELECT b.*,m.name,m.reorder_level FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.units_remaining>0 AND b.expiry_date IS NOT NULL AND b.expiry_date<CURDATE() ORDER BY b.expiry_date,m.name")->fetchAll(); $soon=$db->query("SELECT b.*,m.name,m.reorder_level FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.units_remaining>0 AND b.expiry_date IS NOT NULL AND b.expiry_date>=CURDATE() AND b.expiry_date<=DATE_ADD(CURDATE(),INTERVAL 30 DAY) ORDER BY b.expiry_date,m.name")->fetchAll(); $low=$db->query("SELECT m.id,m.name,m.reorder_level,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 AND m.reorder_level>0 GROUP BY m.id,m.name,m.reorder_level HAVING stock<=m.reorder_level ORDER BY stock,m.name")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock Alerts</title><link rel="stylesheet" href="style.css"><style>.alert-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:18px}.alert-card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:20px}.alert-card strong{display:block;font-size:30px;margin-top:8px}.danger{border-left:5px solid #dc2626}.warning{border-left:5px solid #f59e0b}.low{border-left:5px solid #eab308}@media(max-width:800px){.alert-grid{grid-template-columns:1fr}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">INVENTORY CONTROL</div><h1>Stock Alerts</h1><p>Expired, expiring and low-stock medicines.</p></div></div><div class="alert-grid"><div class="alert-card danger"><small>🔴 EXPIRED BATCHES</small><strong><?=count($expired)?></strong><span>Need attention immediately</span></div><div class="alert-card warning"><small>🟠 EXPIRING IN 30 DAYS</small><strong><?=count($soon)?></strong><span>Plan to sell/return/reorder</span></div><div class="alert-card low"><small>🟡 LOW STOCK</small><strong><?=count($low)?></strong><span>At or below reorder level</span></div></div><section class="panel"><h2>🔴 Expired Batches</h2><table><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Units</th></tr><?php if(!$expired):?><tr><td colspan="4">No expired stock.</td></tr><?php else:foreach($expired as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['batch_no']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=number_format((int)$r['units_remaining'])?></td></tr><?php endforeach;endif;?></table></section><section class="panel"><h2>🟠 Expiring Within 30 Days</h2><table><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Units</th></tr><?php if(!$soon):?><tr><td colspan="4">Nothing expires within 30 days.</td></tr><?php else:foreach($soon as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['batch_no']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=number_format((int)$r['units_remaining'])?></td></tr><?php endforeach;endif;?></table></section><section class="panel"><h2>🟡 Low Stock</h2><table><tr><th>Medicine</th><th>Current Stock</th><th>Reorder Level</th><th>Status</th></tr><?php if(!$low):?><tr><td colspan="4">No medicines are below their reorder level.</td></tr><?php else:foreach($low as $r):?><tr><td><?=e($r['name'])?></td><td><?=number_format((int)$r['stock'])?></td><td><?=number_format((int)$r['reorder_level'])?></td><td><?=((int)$r['stock']===0?'Out of stock':'Reorder soon')?></td></tr><?php endforeach;endif;?></table></section></main></body></html>